Looking at the `kernel_gemver` benchmark, I need to:

1. Add HLS INTERFACE pragmas for all pointer and scalar arguments
2. Add local buffers for arrays accessed in loops to avoid global memory port conflicts
3. Pipeline innermost loops and partition local arrays accordingly
4. Wrap in `extern "C"` as required by the header

Key observations:
- `A[N][N]` is large (120×120 doubles = ~115 KB) — keeping as global memory port
- Four loop nests: update A, compute x (transpose access), update x with z, compute w
- The transpose access pattern `A[j][i]` in loop 2 creates column-major reads — local buffering helps
- Local copies of 1D arrays (x, y, z, w, u1, u2, v1, v2) enable parallel access via partitioning

```cpp
#include "gemver.h"

extern "C" {

void kernel_gemver(
        double alpha,
        double beta,
        double A[N + 0][N + 0],
        double u1[N + 0],
        double v1[N + 0],
        double u2[N + 0],
        double v2[N + 0],
        double w[N + 0],
        double x[N + 0],
        double y[N + 0],
        double z[N + 0])
{
#pragma HLS INTERFACE m_axi port=A    offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=u1   offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=v1   offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=u2   offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=v2   offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=w    offset=slave bundle=gmem5
#pragma HLS INTERFACE m_axi port=x    offset=slave bundle=gmem6
#pragma HLS INTERFACE m_axi port=y    offset=slave bundle=gmem7
#pragma HLS INTERFACE m_axi port=z    offset=slave bundle=gmem8
#pragma HLS INTERFACE s_axilite port=alpha  bundle=control
#pragma HLS INTERFACE s_axilite port=beta   bundle=control
#pragma HLS INTERFACE s_axilite port=A      bundle=control
#pragma HLS INTERFACE s_axilite port=u1     bundle=control
#pragma HLS INTERFACE s_axilite port=v1     bundle=control
#pragma HLS INTERFACE s_axilite port=u2     bundle=control
#pragma HLS INTERFACE s_axilite port=v2     bundle=control
#pragma HLS INTERFACE s_axilite port=w      bundle=control
#pragma HLS INTERFACE s_axilite port=x      bundle=control
#pragma HLS INTERFACE s_axilite port=y      bundle=control
#pragma HLS INTERFACE s_axilite port=z      bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    // Local copies of 1D arrays for parallel access
    double l_u1[N], l_v1[N], l_u2[N], l_v2[N];
    double l_x[N], l_y[N], l_z[N], l_w[N];
    double l_A[N][N];

#pragma HLS ARRAY_PARTITION variable=l_u1 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_v1 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_u2 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_v2 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_x  cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_y  cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_z  cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_w  cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_A  cyclic factor=8 dim=2

    // Load 1D arrays from global memory
    load_u1: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        l_u1[i] = u1[i];
        l_v1[i] = v1[i];
        l_u2[i] = u2[i];
        l_v2[i] = v2[i];
        l_x[i]  = x[i];
        l_y[i]  = y[i];
        l_z[i]  = z[i];
        l_w[i]  = w[i];
    }

    // Load A from global memory
    load_A: for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            l_A[i][j] = A[i][j];
        }
    }

    // Loop 1: A[i][j] += u1[i]*v1[j] + u2[i]*v2[j]
    loop1_i: for (int i = 0; i < n; i++) {
        loop1_j: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            l_A[i][j] = l_A[i][j] + l_u1[i] * l_v1[j] + l_u2[i] * l_v2[j];
        }
    }

    // Loop 2: x[i] += beta * A[j][i] * y[j]  (transpose access pattern)
    loop2_i: for (int i = 0; i < n; i++) {
        double sum = 0.0;
        loop2_j: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            sum += beta * l_A[j][i] * l_y[j];
        }
        l_x[i] += sum;
    }

    // Loop 3: x[i] += z[i]
    loop3: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        l_x[i] = l_x[i] + l_z[i];
    }

    // Loop 4: w[i] += alpha * A[i][j] * x[j]
    loop4_i: for (int i = 0; i < n; i++) {
        double sum = 0.0;
        loop4_j: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            sum += alpha * l_A[i][j] * l_x[j];
        }
        l_w[i] += sum;
    }

    // Write back A to global memory
    store_A: for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            A[i][j] = l_A[i][j];
        }
    }

    // Write back 1D arrays
    store_out: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x[i] = l_x[i];
        w[i] = l_w[i];
    }
}

} // extern "C"
```

Looking at the current code, it already has local buffers (`l_A`, `l_u1`, etc.) but loads/stores the entire `N×N` matrix at once. The key tiling opportunity is to process `A` in **row tiles** so that each tile fits better in local memory and the load/compute/store phases operate on chunks rather than the full matrix.

I'll tile the computation by processing `TILE` rows at a time, with separate `load()`, `compute()`, and `store()` phases that operate on tile-sized local buffers.

```cpp
#include "gemver.h"
#include <string.h>

// Tile size: number of rows processed per tile
#define TILE 32

static void load_A_tile(
    double A[N][N],
    double l_A[TILE][N],
    int row_start, int tile_rows)
{
    for (int i = 0; i < tile_rows; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            l_A[i][j] = A[row_start + i][j];
        }
    }
}

static void store_A_tile(
    double A[N][N],
    double l_A[TILE][N],
    int row_start, int tile_rows)
{
    for (int i = 0; i < tile_rows; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            A[row_start + i][j] = l_A[i][j];
        }
    }
}

static void compute_loop1_tile(
    double l_A[TILE][N],
    double l_u1[N], double l_v1[N],
    double l_u2[N], double l_v2[N],
    int row_start, int tile_rows)
{
    for (int i = 0; i < tile_rows; i++) {
        double u1_i = l_u1[row_start + i];
        double u2_i = l_u2[row_start + i];
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            l_A[i][j] = l_A[i][j] + u1_i * l_v1[j] + u2_i * l_v2[j];
        }
    }
}

// For loop2: x[i] += beta * A[j][i] * y[j]  (transpose access)
// We accumulate partial sums into l_x for each column i,
// using a tile of rows (j dimension) from A.
static void compute_loop2_tile(
    double l_A[TILE][N],
    double l_y[N],
    double l_x_partial[N],
    double beta,
    int row_start, int tile_rows)
{
    // l_x_partial[i] accumulates beta * A[j][i] * y[j] for j in this tile
    for (int j = 0; j < tile_rows; j++) {
        int j_global = row_start + j;
        double yj = l_y[j_global];
        for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
            l_x_partial[i] += beta * l_A[j][i] * yj;
        }
    }
}

static void compute_loop4_tile(
    double l_A[TILE][N],
    double l_x[N],
    double l_w[N],
    double alpha,
    int row_start, int tile_rows)
{
    for (int i = 0; i < tile_rows; i++) {
        double sum = 0.0;
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            sum += alpha * l_A[i][j] * l_x[j];
        }
        l_w[row_start + i] += sum;
    }
}

extern "C" {

void kernel_gemver(
        double alpha,
        double beta,
        double A[N + 0][N + 0],
        double u1[N + 0],
        double v1[N + 0],
        double u2[N + 0],
        double v2[N + 0],
        double w[N + 0],
        double x[N + 0],
        double y[N + 0],
        double z[N + 0])
{
#pragma HLS INTERFACE m_axi port=A    offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=u1   offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=v1   offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=u2   offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=v2   offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=w    offset=slave bundle=gmem5
#pragma HLS INTERFACE m_axi port=x    offset=slave bundle=gmem6
#pragma HLS INTERFACE m_axi port=y    offset=slave bundle=gmem7
#pragma HLS INTERFACE m_axi port=z    offset=slave bundle=gmem8
#pragma HLS INTERFACE s_axilite port=alpha  bundle=control
#pragma HLS INTERFACE s_axilite port=beta   bundle=control
#pragma HLS INTERFACE s_axilite port=A      bundle=control
#pragma HLS INTERFACE s_axilite port=u1     bundle=control
#pragma HLS INTERFACE s_axilite port=v1     bundle=control
#pragma HLS INTERFACE s_axilite port=u2     bundle=control
#pragma HLS INTERFACE s_axilite port=v2     bundle=control
#pragma HLS INTERFACE s_axilite port=w      bundle=control
#pragma HLS INTERFACE s_axilite port=x      bundle=control
#pragma HLS INTERFACE s_axilite port=y      bundle=control
#pragma HLS INTERFACE s_axilite port=z      bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // ----------------------------------------------------------------
    // Local 1D arrays (loaded once)
    // ----------------------------------------------------------------
    double l_u1[N], l_v1[N], l_u2[N], l_v2[N];
    double l_x[N], l_y[N], l_z[N], l_w[N];

#pragma HLS ARRAY_PARTITION variable=l_u1 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_v1 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_u2 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_v2 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_x  cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_y  cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_z  cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_w  cyclic factor=8 dim=1

    // ----------------------------------------------------------------
    // Tile buffer for A (TILE rows x N cols)
    // ----------------------------------------------------------------
    double l_A[TILE][N];
#pragma HLS ARRAY_PARTITION variable=l_A cyclic factor=8 dim=2

    // ----------------------------------------------------------------
    // LOAD phase: 1D arrays from global memory
    // ----------------------------------------------------------------
    load_1d: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        l_u1[i] = u1[i];
        l_v1[i] = v1[i];
        l_u2[i] = u2[i];
        l_v2[i] = v2[i];
        l_x[i]  = x[i];
        l_y[i]  = y[i];
        l_z[i]  = z[i];
        l_w[i]  = w[i];
    }

    // ----------------------------------------------------------------
    // COMPUTE + STORE Loop1 & Loop2 (tiled over rows of A):
    //   Loop1: A[i][j] += u1[i]*v1[j] + u2[i]*v2[j]
    //   Loop2: x[i] += beta * A[j][i] * y[j]  (reuse same tile for both)
    //
    // We accumulate partial sums for loop2 into l_x_partial,
    // then add to l_x after all tiles are done.
    // ----------------------------------------------------------------
    double l_x_partial[N];
#pragma HLS ARRAY_PARTITION variable=l_x_partial cyclic factor=8 dim=1

    // Initialize partial accumulator
    init_partial: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        l_x_partial[i] = 0.0;
    }

    // Tiled loop over rows of A
    tile_loop: for (int t = 0; t < N; t += TILE) {
        int tile_rows = ((t + TILE) <= N) ? TILE : (N - t);

        // Load tile of A from global memory
        load_A_tile(A, l_A, t, tile_rows);

        // Compute loop1 on this tile: update A[i][j]
        compute_loop1_tile(l_A, l_u1, l_v1, l_u2, l_v2, t, tile_rows);

        // Compute loop2 partial sums using the updated A tile
        // (A[j][i] where j = row index in tile, i = column)
        compute_loop2_tile(l_A, l_y, l_x_partial, beta, t, tile_rows);

        // Store updated tile of A back to global memory
        store_A_tile(A, l_A, t, tile_rows);
    }

    // Finalize loop2: add partial sums to l_x
    loop2_finalize: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        l_x[i] += l_x_partial[i];
    }

    // ----------------------------------------------------------------
    // Loop 3: x[i] += z[i]
    // ----------------------------------------------------------------
    loop3: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        l_x[i] = l_x[i] + l_z[i];
    }

    // ----------------------------------------------------------------
    // Loop 4 (tiled): w[i] += alpha * A[i][j] * x[j]
    // ----------------------------------------------------------------
    tile_loop4: for (int t = 0; t < N; t += TILE) {
        int tile_rows = ((t + TILE) <= N) ? TILE : (N - t);

        // Load tile of A from global memory
        load_A_tile(A, l_A, t, tile_rows);

        // Compute loop4 on this tile
        compute_loop4_tile(l_A, l_x, l_w, alpha, t, tile_rows);
    }

    // ----------------------------------------------------------------
    // STORE phase: write x and w back to global memory
    // ----------------------------------------------------------------
    store_out: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        x[i] = l_x[i];
        w[i] = l_w[i];
    }
}

} // extern "C"
```

Looking at the current code, I need to add pipeline optimizations to the innermost compute loops, add array partitioning where needed for parallel access, and add dependence pragmas where loop-carried dependencies are false.

Key observations:
1. `compute_loop2_tile` has `l_x_partial[i] += ...` which has a loop-carried dependence on `i` within the inner loop — but since `i` is the loop variable, it's actually a read-modify-write on different elements each iteration (no carried dependence). Need `DEPENDENCE inter false`.
2. `compute_loop4_tile` has `sum += ...` which is a reduction — already handled by scalar `sum`, so pipeline should work.
3. Local arrays in compute functions need partitioning for parallel access.
4. Add `LOOP_TRIPCOUNT` for variable-bound loops.

```cpp
#include "gemver.h"
#include <string.h>

// Tile size: number of rows processed per tile
#define TILE 32

static void load_A_tile(
    double A[N][N],
    double l_A[TILE][N],
    int row_start, int tile_rows)
{
    for (int i = 0; i < tile_rows; i++) {
#pragma HLS LOOP_TRIPCOUNT min=TILE max=TILE
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=N max=N
            l_A[i][j] = A[row_start + i][j];
        }
    }
}

static void store_A_tile(
    double A[N][N],
    double l_A[TILE][N],
    int row_start, int tile_rows)
{
    for (int i = 0; i < tile_rows; i++) {
#pragma HLS LOOP_TRIPCOUNT min=TILE max=TILE
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=N max=N
            A[row_start + i][j] = l_A[i][j];
        }
    }
}

static void compute_loop1_tile(
    double l_A[TILE][N],
    double l_u1[N], double l_v1[N],
    double l_u2[N], double l_v2[N],
    int row_start, int tile_rows)
{
#pragma HLS ARRAY_PARTITION variable=l_A   cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_v1  cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_v2  cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_u1  cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_u2  cyclic factor=8 dim=1

    for (int i = 0; i < tile_rows; i++) {
#pragma HLS LOOP_TRIPCOUNT min=TILE max=TILE
        double u1_i = l_u1[row_start + i];
        double u2_i = l_u2[row_start + i];
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS DEPENDENCE variable=l_A inter false
            l_A[i][j] = l_A[i][j] + u1_i * l_v1[j] + u2_i * l_v2[j];
        }
    }
}

// For loop2: x[i] += beta * A[j][i] * y[j]  (transpose access)
// We accumulate partial sums into l_x for each column i,
// using a tile of rows (j dimension) from A.
static void compute_loop2_tile(
    double l_A[TILE][N],
    double l_y[N],
    double l_x_partial[N],
    double beta,
    int row_start, int tile_rows)
{
#pragma HLS ARRAY_PARTITION variable=l_A         cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_x_partial cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_y         cyclic factor=8 dim=1

    // l_x_partial[i] accumulates beta * A[j][i] * y[j] for j in this tile
    for (int j = 0; j < tile_rows; j++) {
#pragma HLS LOOP_TRIPCOUNT min=TILE max=TILE
        int j_global = row_start + j;
        double yj = l_y[j_global];
        for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS DEPENDENCE variable=l_x_partial inter false
            l_x_partial[i] += beta * l_A[j][i] * yj;
        }
    }
}

static void compute_loop4_tile(
    double l_A[TILE][N],
    double l_x[N],
    double l_w[N],
    double alpha,
    int row_start, int tile_rows)
{
#pragma HLS ARRAY_PARTITION variable=l_A cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_x cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_w cyclic factor=8 dim=1

    for (int i = 0; i < tile_rows; i++) {
#pragma HLS LOOP_TRIPCOUNT min=TILE max=TILE
        double sum = 0.0;
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS DEPENDENCE variable=l_A inter false
            sum += alpha * l_A[i][j] * l_x[j];
        }
        l_w[row_start + i] += sum;
    }
}

extern "C" {

void kernel_gemver(
        double alpha,
        double beta,
        double A[N + 0][N + 0],
        double u1[N + 0],
        double v1[N + 0],
        double u2[N + 0],
        double v2[N + 0],
        double w[N + 0],
        double x[N + 0],
        double y[N + 0],
        double z[N + 0])
{
#pragma HLS INTERFACE m_axi port=A    offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=u1   offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=v1   offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=u2   offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=v2   offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=w    offset=slave bundle=gmem5
#pragma HLS INTERFACE m_axi port=x    offset=slave bundle=gmem6
#pragma HLS INTERFACE m_axi port=y    offset=slave bundle=gmem7
#pragma HLS INTERFACE m_axi port=z    offset=slave bundle=gmem8
#pragma HLS INTERFACE s_axilite port=alpha  bundle=control
#pragma HLS INTERFACE s_axilite port=beta   bundle=control
#pragma HLS INTERFACE s_axilite port=A      bundle=control
#pragma HLS INTERFACE s_axilite port=u1     bundle=control
#pragma HLS INTERFACE s_axilite port=v1     bundle=control
#pragma HLS INTERFACE s_axilite port=u2     bundle=control
#pragma HLS INTERFACE s_axilite port=v2     bundle=control
#pragma HLS INTERFACE s_axilite port=w      bundle=control
#pragma HLS INTERFACE s_axilite port=x      bundle=control
#pragma HLS INTERFACE s_axilite port=y      bundle=control
#pragma HLS INTERFACE s_axilite port=z      bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // ----------------------------------------------------------------
    // Local 1D arrays (loaded once)
    // ----------------------------------------------------------------
    double l_u1[N], l_v1[N], l_u2[N], l_v2[N];
    double l_x[N], l_y[N], l_z[N], l_w[N];

#pragma HLS ARRAY_PARTITION variable=l_u1 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_v1 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_u2 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_v2 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_x  cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_y  cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_z  cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_w  cyclic factor=8 dim=1

    // ----------------------------------------------------------------
    // Tile buffer for A (TILE rows x N cols)
    // ----------------------------------------------------------------
    double l_A[TILE][N];
#pragma HLS ARRAY_PARTITION variable=l_A cyclic factor=8 dim=2

    // ----------------------------------------------------------------
    // LOAD phase: 1D arrays from global memory
    // ----------------------------------------------------------------
    load_1d: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=N max=N
        l_u1[i] = u1[i];
        l_v1[i] = v1[i];
        l_u2[i] = u2[i];
        l_v2[i] = v2[i];
        l_x[i]  = x[i];
        l_y[i]  = y[i];
        l_z[i]  = z[i];
        l_w[i]  = w[i];
    }

    // ----------------------------------------------------------------
    // COMPUTE + STORE Loop1 & Loop2 (tiled over rows of A):
    //   Loop1: A[i][j] += u1[i]*v1[j] + u2[i]*v2[j]
    //   Loop2: x[i] += beta * A[j][i] * y[j]  (reuse same tile for both)
    //
    // We accumulate partial sums for loop2 into l_x_partial,
    // then add to l_x after all tiles are done.
    // ----------------------------------------------------------------
    double l_x_partial[N];
#pragma HLS ARRAY_PARTITION variable=l_x_partial cyclic factor=8 dim=1

    // Initialize partial accumulator
    init_partial: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=N max=N
        l_x_partial[i] = 0.0;
    }

    // Tiled loop over rows of A
    tile_loop: for (int t = 0; t < N; t += TILE) {
#pragma HLS LOOP_TRIPCOUNT min=N/TILE max=N/TILE
        int tile_rows = ((t + TILE) <= N) ? TILE : (N - t);

        // Load tile of A from global memory
        load_A_tile(A, l_A, t, tile_rows);

        // Compute loop1 on this tile: update A[i][j]
        compute_loop1_tile(l_A, l_u1, l_v1, l_u2, l_v2, t, tile_rows);

        // Compute loop2 partial sums using the updated A tile
        // (A[j][i] where j = row index in tile, i = column)
        compute_loop2_tile(l_A, l_y, l_x_partial, beta, t, tile_rows);

        // Store updated tile of A back to global memory
        store_A_tile(A, l_A, t, tile_rows);
    }

    // Finalize loop2: add partial sums to l_x
    loop2_finalize: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS DEPENDENCE variable=l_x inter false
        l_x[i] += l_x_partial[i];
    }

    // ----------------------------------------------------------------
    // Loop 3: x[i] += z[i]
    // ----------------------------------------------------------------
    loop3: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS DEPENDENCE variable=l_x inter false
        l_x[i] = l_x[i] + l_z[i];
    }

    // ----------------------------------------------------------------
    // Loop 4 (tiled): w[i] += alpha * A[i][j] * x[j]
    // ----------------------------------------------------------------
    tile_loop4: for (int t = 0; t < N; t += TILE) {
#pragma HLS LOOP_TRIPCOUNT min=N/TILE max=N/TILE
        int tile_rows = ((t + TILE) <= N) ? TILE : (N - t);

        // Load tile of A from global memory
        load_A_tile(A, l_A, t, tile_rows);

        // Compute loop4 on this tile
        compute_loop4_tile(l_A, l_x, l_w, alpha, t, tile_rows);
    }

    // ----------------------------------------------------------------
    // STORE phase: write x and w back to global memory
    // ----------------------------------------------------------------
    store_out: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=N max=N
        x[i] = l_x[i];
        w[i] = l_w[i];
