    store_out: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
#pragma HLS LOOP_TRIPCOUNT min=N max=N
        x[i] = l_x[i];
        w[i] = l_w[i];
